/* ================= AI AGENTS — types, tiles, editor, builder chat, test & review ================= */
S.ag={acc:{},type:'sales',sel:'s1',sec:'overview',view:'tiles',test:{},tmode:'chat',lb:{type:'all',camp:'all',dir:'all',period:'30',sort:'score'}};
TITLES.agents=()=>'<b>AI Agents</b>'+(S.ag.view==='leaderboard'?' › Leaderboard':'');
A.openAgent=el=>{hidePop();const a=agent(el.dataset.id);if(!a)return;S.ag.type=a.type;S.ag.sel=a.id;S.ag.view='tiles';go('agents');setTimeout(()=>{const e=$('#aged');if(e)e.scrollIntoView({behavior:'smooth',block:'start'})},60)};
const ACTIONS=[['Calling','phone',[['callOut','Make calls'],['callIn','Handle calls (answer incoming calls)'],['voicemail','Leave voicemail'],['transferCall','Transfer a call to a person'],['record','Record calls']]],['Messaging','sms',[['sms','Send texts (SMS)'],['wa','Send WhatsApp, Messenger & Instagram messages'],['email','Send emails'],['media','Send pictures, files and links']]],['Database','db',[['stages','Update lead stages from the conversation'],['fields','Update contact fields when new information comes up'],['tags','Update tags from the conversation'],['comments','Add comments for other agents and your team'],['tasks','Create tasks for your team']]],['Bookings','calendar',[['booking','Book, move and cancel appointments'],['reminders','Send booking reminders']]],['Sales & money','dollar',[['quote','Create and send quotations'],['paylink','Send a payment link'],['sale','Record a sale'],['invoice','Create and send invoices'],['refund','Request refunds (needs your approval)']]],['Connections','link',[['http','Make HTTP requests (call your systems via API)'],['route','Route to the right agent (billing → Finance, tech → Tech support, sales → Sales)']]]];
const ACT_TECH=['Tech support extras','wrench',[['ticket','Create support tickets'],['diag','Run guided troubleshooting'],['status','Check order / service status'],['reset','Reset passwords or devices (via API)'],['escalate','Escalate to your engineering team']]];
const ACT_FIN=['Finance extras','receipt',[['recurring','Recurring billing'],['reminder','Payment reminders'],['plans','Offer payment plans'],['tax','Apply taxes'],['receipt','Send receipts'],['multicur','Multi-currency invoices']]];
const RULES=[['Hand over to a person when…','hand',[['askHuman','Customer asks for a human or a manager'],['angry','Customer is angry or upset'],['unknown','Agent doesn’t know the answer (twice)'],['noInfo','Required information can’t be obtained'],['unclear','Qualification is unclear'],['legal','Customer asks for legal, medical or financial advice']]],['Safety','shield',[['noPrice','Never change pricing'],['noDiscount','Never offer discounts above the limit'],['noPromise','Never promise availability that isn’t on the calendar'],['noPII','Never ask for card numbers or passwords in chat']]],['Compliance','lock',[['disclose','Say it’s an AI assistant at the start'],['optout','Honour opt-out words in any language'],['recordNotice','Play a recording notice on calls'],['quiet','Respect quiet hours (8 AM – 9 PM local)']]],['Working hours','clock',[['hours24','Work 24/7'],['afterHours','After hours: take a message and book a call-back']]]];

/* ---------- list / tiles ---------- */
VIEWS.agents=()=>{if(S.ag.view==='leaderboard')return vLeaderboard();const t=S.ag.type,L=D.agents.filter(a=>a.type===t);const a=agent(S.ag.sel);if(!a||a.type!==t)S.ag.sel=L[0].id;
 return `<div class="page wide" style="max-width:1480px"><div class="ph"><div><h1>AI Agents</h1><p class="sub">Your AI team. Every agent can call, text and email. Pick a type, compare agents by their results, and open one to set it up — usually 1–2 minutes with AI.</p></div><div class="row">${btn('Leaderboard','agView',{k:'sm',i:'chart',a:'data-v="leaderboard"'})}${aiBtn('Create agent with AI','agCreate','','sm')}${btn('New agent','agCreate',{k:'sm primary',i:'plus',a:'data-blank="1"'})}</div></div>
 <div class="atypes">${Object.entries(AT).map(([k,v])=>`<button class="atype ${t===k?'on':''}" data-act="agType" data-v="${k}" data-tip="${esc(v.d)}"><span class="ico">${ic(v.i,15)}</span><span class="trunc"><b>${v.l}</b><span>${D.agents.filter(x=>x.type===k).length} agents</span></span></button>`).join('')}</div>
 <div class="grid g3" style="margin-bottom:8px">${L.map(x=>agTile(x)).join('')}</div>
 <div id="aged" style="scroll-margin-top:12px">${agEditor(agent(S.ag.sel))}</div></div>`};
function agTile(x){const on=x.id===S.ag.sel;return `<div class="atile ${on?'on':''}" role="button" tabindex="0" data-act="agSel" data-id="${x.id}"><div class="row nw"><span class="av bot lg">${ic(AT[x.type].i,18)}</span><div class="grow" style="min-width:0"><div class="row"><b style="font-size:15px">${x.name}</b>${x.status==='live'?bdg('<span class="dot"></span>Live','good'):bdg('Ready')}${x.edited?bdg('Edited in your account','blue'):bdg('Default')}</div><div class="small muted trunc">${esc(x.voice)} · ${x.mode} · v${x.ver}</div></div></div>
 <div class="mt">${AT[x.type].m.map(([k,l,u])=>`<div data-tip="${esc(l)} · your workspace"><b>${u==='$'?money(x.ws[k]):nf(x.ws[k])+(u==='%'?'%':'')}</b><span>${l}</span></div>`).join('')}</div>
 <div class="row small muted" style="gap:10px"><span>${nf(x.ws.msgs)} messages</span><span>${nf(x.ws.replies)} replies</span><span>${nf(x.ws.calls)} calls</span><span>${x.ws.success}% success</span></div>
 <div class="gscore" data-tip="Across ${x.global.accounts} businesses on Crewline. Only your own campaign details are visible to you.">${ic('globe',12)}Global score: <b style="color:var(--ink)">${x.global.success}%</b> success · <b style="color:var(--ink)">${x.global.conv}%</b> conversion</div>
 <div class="row">${btn('More details','agHistory',{k:'xs',a:`data-id="${x.id}"`})}${btn('Assign to','agAssign',{k:'xs',i:'arrowr',a:`data-id="${x.id}"`})}${x.camps.length?`<span class="small muted trunc">On ${x.camps.map(k=>esc(camp(k).name.split(' — ')[0])).join(', ')}</span>`:''}</div></div>`}
A.agType=el=>{S.ag.type=el.dataset.v;S.ag.sel=D.agents.find(a=>a.type===el.dataset.v).id;S.ag.sec='overview';rr()};
A.agSel=(el,e)=>{if(e&&e.target.closest('button')&&e.target.closest('button')!==el)return;S.ag.sel=el.dataset.id;S.ag.sec='overview';rr();setTimeout(()=>{const d=$('#aged');if(d)d.scrollIntoView({behavior:'smooth',block:'start'})},40)};
A.agView=el=>{S.ag.view=el.dataset.v;rr();renderTop()};

/* ---------- editor ---------- */
const AGSEC=[['overview','Overview','user'],['instr','Instructions','edit'],['job','Job','target'],['qa','Q&A','query'],['know','What they know','book'],['can','What they can do','zap'],['rules','Rules & handover','shield'],['follow','Follow-ups','refresh'],['booking','Bookings','calendar']];
function agEditor(a){const sec=S.ag.sec;const camps=a.camps.map(k=>camp(k));
 return `<div class="card" style="margin-bottom:12px"><div class="card-h" style="min-height:64px"><div class="row nw" style="gap:12px;min-width:0"><span class="av bot lg">${ic(AT[a.type].i,18)}</span><div style="min-width:0"><h2 style="font-size:18px">${esc(a.name)} <span class="muted" style="font-weight:500">— ${a.mode}</span></h2><div class="small muted trunc">${AT[a.type].l} agent · ${camps.length?camps.map(c=>esc(c.biz)).filter((x,i,s)=>s.indexOf(x)===i).join(', '):'Not on a campaign yet'} · v${a.ver}</div></div></div>
  <div class="row">${aiBtn('Analyze with AI','agAnalyze',`data-id="${a.id}"`,'sm')}${btn('Versions','agVersions',{k:'sm ghost',i:'history'})}${sel(a.versions.slice().reverse().map(v=>[v.v,`v${v.v} · ${v.label}`]),a.ver,'data-chg="agVer" aria-label="Version"','sm auto')}${btn('Save changes','agSave',{k:'sm primary',i:'check'})}</div></div>
  <div class="banner ai" style="margin:12px 20px 0">${ic('spark',16)}<div class="grow"><b>Create / edit your agent with AI</b><div class="small muted">Talk or type — AI asks one question at a time, writes back what it understood and asks “Am I correct?”. It fills every field below for you.</div></div>${btn('Start','openBuilder',{k:'primary sm',i:'mic',a:`data-ctx="agent"`})}</div>
  ${a.needsInfo?`<div class="banner warn" style="margin:12px 20px 0">${ic('alert',15)}<div class="grow"><b>Update your agent</b><div class="small">${esc(a.name)} needs your business details before it can go live (products, qualifying criteria, handover).</div></div>${btn('Answer with AI','openBuilder',{k:'sm primary',a:'data-ctx="agent"'})}${btn('Answer one by one','agSec',{k:'sm',a:'data-v="job"'})}</div>`:''}
  <div class="row" style="margin:12px 20px 0;gap:6px">${camps.length?camps.map(c=>`<button class="bdg line" data-act="nav" data-v="campaign" data-p='{"id":"${c.id}"}'>${dirIc(c.dir)} ${esc(c.name)}</button>`).join(''):''}${btn('Assign to…','agAssign',{k:'xs',a:`data-id="${a.id}"`})}</div>
  <div class="aed" style="padding:12px 20px 20px"><div class="card" style="min-width:0"><div class="aed-nav">${AGSEC.map(s=>`<button class="tab ${sec===s[0]?'on':''}" data-act="agSec" data-v="${s[0]}">${ic(s[2],13)}${s[1]}</button>`).join('')}</div><div class="aed-sec stack">${AGS[sec](a)}</div></div>
  <div class="stack">${agReview(a)}${agTest(a)}</div></div></div>`}
A.agSec=el=>{S.ag.sec=el.dataset.v;rr()};
const AGS={};
AGS.overview=a=>`<div class="fgrid two">${fld('Name',`<input class="in" value="${esc(a.name)}" data-inp="agV" data-k="name">`)}${fld('Agent type',sel(Object.entries(AT).map(([k,v])=>[k,v.l]),a.type,'data-chg="agType2"'))}</div>
 ${fld('Voice agent or chat agent?',`<div class="row">${seg([['Voice agent','Voice agent','phone'],['Chat agent','Chat agent','sms']],a.mode,'agMode')}<span class="help">A label to avoid confusion — every agent can still call, text and email. Switching asks you to rename the agent.</span></div>`)}
 ${fld('Works on',seg([['out','Outbound only','out'],['in','Inbound only','in'],['both','Both','swap']],a.dir,'agDir'))}
 ${fld('Languages',`<div class="choice">${['Any language (auto)','English','Urdu','Spanish','French','Arabic','Hindi','Punjabi','Chinese','Portuguese'].map(l=>`<button class="${a.langs.includes(l)?'on':''}" data-act="agLang" data-v="${esc(l)}">${esc(l)}</button>`).join('')}</div>`)}
 ${fld('Voice',`<div class="row">${sel(D.voices.map(v=>[v[0]+' · '+v[1],v[0]+' — '+v[1]]),D.voices.find(v=>a.voice.startsWith(v[0]))?D.voices.find(v=>a.voice.startsWith(v[0])).join(' · '):'',`data-chg="agVoice" style="max-width:340px"`)}${btn('Play sample','toast',{k:'sm',i:'play',a:'data-m="Playing voice sample (prototype)"'})}${btn('Clone a voice','voiceClone',{k:'sm',i:'mic'})}</div>`,'Voices by ElevenLabs (or another voice provider). You can clone your own voice.')}
 <div class="stack-s"><div class="lbl">How ${esc(a.name)} talks — per channel</div>${[['call','On calls','phone'],['text','In texts & chats','sms'],['email','In emails','mail']].map(([k,l,i])=>`<div class="row nw" style="align-items:flex-start"><span class="plat lg" style="margin-top:2px">${ic(i,14)}</span><div class="grow">${fld(l,`<input class="in" id="sty-${k}" value="${esc(a.style[k])}" data-inp="agSty" data-k="${k}">`)}</div>${btn('Improve','aiFill',{k:'xs ai',i:'spark',a:`data-target="#sty-${k}" data-text="${esc({call:'Warm and relaxed, short sentences, pauses to let the customer talk, never pushy',text:'Friendly and short (1–2 sentences), one question at a time, one emoji max',email:'Clear subject, 3 short paragraphs, bullet points for prices, polite sign-off with name'}[k])}" style="margin-top:22px"`})}</div>`).join('')}</div>
 ${optRow('Status',a.status==='live'?'Live on '+a.camps.length+' campaigns':'Ready — assign it to a campaign to go live',seg([['live','Live'],['ready','Paused']],a.status,'agStatus'))}`;
AGS.instr=a=>`<div class="banner">${ic('lock',15)}<span class="small">The core prompt is written by Crewline and stays hidden. You edit the <b>business layer</b> — your campaign info, script, criteria, dos & don’ts. Changes apply <b>only in your account</b>.</span></div>
 ${fld('Start from a template',`<div class="row">${sel(D.promptTemplates[a.type],a.template,'data-chg="agTpl" style="max-width:320px"')}${btn('Use as it is','toast',{k:'sm',a:'data-m="Template applied"'})}${btn('Edit it','agSec',{k:'sm ghost',a:'data-v="instr"'})}</div>`,'Pre-written by Crewline for this agent type.')}
 ${fld('Instructions',`<textarea class="in" id="agInstr" style="min-height:180px" data-inp="agV" data-k="instr">${esc(a.instr)}</textarea>`)}
 <div class="row">${btn('Take help from AI','openBuilder',{k:'sm ai',i:'spark',a:'data-ctx="agent"'})}${btn('Optimize with AI','aiFill',{k:'sm ai',i:'spark',a:`data-target="#agInstr" data-text="${esc(`ROLE: You are ${a.name}, the ${AT[a.type].l.toLowerCase()} agent for {business}.\nGOAL: ${a.job.goal}.\nSTYLE: ${a.style.text}. One question at a time.\nFLOW: 1) Greet and say you are an AI assistant. 2) Explain the offer in one sentence with the price. 3) Ask the qualifying questions in order. 4) If qualified → book / close and move the stage. 5) If unsure → mark Needs review.\nNEVER: change prices, promise dates not on the calendar, ask for card numbers.\nHANDOVER: if they ask for a person or are upset, hand over right away.`)}" data-done="Rewritten in Crewline’s standard structure"`})}${micBtn('#agInstr','Please be more relaxed and always mention free installation','sm')}</div>`;
AGS.job=a=>{const j=a.job;const acc=(t,i,b,badge='',open)=>`<div class="acc"><button data-act="accT" data-key="${esc(t)}">${ic(i,15)}${t}<span class="st">${badge}</span></button><div class="ab2" ${(S.ag.acc[t]??open)?'':'hidden'}>${b}</div></div>`;const pl=D.stages[(camp(a.camps[0])||{pipe:'telecom'}).pipe].out;
 return `<div class="note"><b>Build order:</b> 1 Stages → 2 Script → 3 Knowledge base → 4 Everything else. You can’t go live until the required answers are filled — or let AI ask you.</div>
 ${acc('1 · Stages this agent uses','kanban',`<div class="row" style="gap:4px">${pl.map(s=>`<span class="stg"><i style="background:${s.c}"></i>${esc(s.n)}</span>`).join('')}</div><div class="row">${btn('Change stages','nav',{k:'sm',a:'data-v="stages"'})}${fld('When qualified, move to',sel(pl.map(s=>s.n),j.whenQual,'data-chg="agJob" data-k="whenQual"','sm auto'))}</div><span class="help">Stage conditions (qualified, cancelled, pending…) are written into the prompt automatically.</span>`,bdg(pl.length+' stages','good'),1)}
 ${acc('2 · Script (optional)','file',`<textarea class="in" id="agScr" data-inp="agJ" data-k="script" placeholder="Paste or dictate a script">${esc(j.script)}</textarea><div class="row">${micBtn('#agScr','Start by saying hi and that you are calling about internet','sm')}${attBtn('sm','Attach a script file')}</div>`,j.script?bdg('Added','good'):bdg('Optional'))}
 ${acc('3 · Knowledge base','book',`<span class="small muted">${a.kb.length} folders · ${a.kb.reduce((x,f)=>x+f.items.length,0)} items</span>${btn('Open knowledge','agSec',{k:'sm',a:'data-v="know"'})}`,bdg(a.kb.length+' folders','good'))}
 ${acc('Purpose & goal','target',`${fld('Primary purpose',`<div class="choice">${['Generate leads','Qualify leads','Sell products','Book appointments','Schedule installation','Follow up with leads','Reactivate old leads','Upsell existing customers','Cross-sell products','Collect customer information','Transfer qualified leads to a human','Solve customer problems','Send invoices','Collect payments','Other'].map(p=>`<button class="${j.purposes.includes(p)?'on':''}" data-act="agJT" data-k="purposes" data-v="${esc(p)}">${p}</button>`).join('')}</div>`)}${fld('Main goal',`<div class="choice">${['Qualify the lead','Make the sale','Book an appointment','Generate a callback','Transfer to a human','Resolve the request','Other'].map(p=>`<button class="${j.goal===p?'on':''}" data-act="agJS" data-k="goal" data-v="${esc(p)}">${p}</button>`).join('')}</div>`)}`,bdg('Required','bad'),1)}
 ${acc('Customers','users',`${fld('Target customer',seg([['Individuals','Individuals'],['Businesses','Businesses'],['Both','Both']],j.target,'agJS','data-k="target"'))}${optRow('Anyone you don’t want to target?','',sw(j.exclude.on,'agExcl'))}${j.exclude.on?`<input class="in" value="${esc(j.exclude.who)}" data-inp="agEx">`:''}`)}
 ${acc('Products & pricing','dollar',`${fld('What are you selling?',`<textarea class="in" id="agProd" data-inp="agJ" data-k="products">${esc(j.products)}</textarea>`)}${fld('Pricing — type, speak or attach a picture',`<textarea class="in" id="agPrice" data-inp="agJ" data-k="pricing">${esc(j.pricing)}</textarea><div class="row">${attBtn('sm','Attach a picture of your price list')}${micBtn('#agPrice','Phone line 20 dollars a month, internet 50, TV 10','sm')}${aiBtn('Read picture with AI','agPricePic','','sm')}</div>`)}${fld('Billing type',seg([['One-time','One-time'],['Monthly','Monthly'],['Annual','Annual'],['Not relevant','Not relevant']],j.billing,'agJS','data-k="billing"'))}${fld('Who is eligible',led('agel',j.eligible,'Type who can buy'))}${fld('Who is NOT eligible',led('agnel',j.notEligible,'Type who can’t buy'))}${fld('Important product information',led('agimp',j.important,'Type an important fact'))}${fld('Product recommendation rules',led('agrec',j.rec,'e.g. 3+ people → Internet 1 Gig'))}`,bdg('Required','bad'))}
 ${acc('Qualifying & disqualifying criteria','check',`${fld('Qualified when… (one sentence per line)',led('agq',j.qual,'Type a criterion',{imp:1,sample:'Customer is moving in the next 30 days'}))}${fld('Disqualified when…',led('agd',j.disq,'Type a criterion',{imp:1}))}`,bdg(j.qual.length+' / '+j.disq.length))}
 ${acc('Questions & information to collect','query',`<div class="card tw"><table class="t compact"><thead><tr><th>#</th><th>Question</th><th>Required?</th><th>Max attempts</th><th>If yes / if no</th><th></th></tr></thead><tbody>${j.questions.map((q,i)=>`<tr><td class="num">${i+1}</td><td><input class="in sm" value="${esc(q.q)}" data-chg="agQ" data-i="${i}" data-k="q" style="min-width:220px"></td><td>${sel(['Required','Optional','Not required'],q.req,`data-chg="agQ" data-i="${i}" data-k="req"`,'sm auto')}</td><td>${sel(['Once','Twice','Three times','Until answered','Custom'],q.att,`data-chg="agQ" data-i="${i}" data-k="att"`,'sm auto')}</td><td><input class="in sm" value="${esc(q.cond)}" placeholder="e.g. Yes → ask X · No → ask Y" data-chg="agQ" data-i="${i}" data-k="cond" style="min-width:200px"></td><td class="row nw">${iconBtn('up','agQMove','Move up',`data-i="${i}" data-d="-1"`,'xs')}${iconBtn('dn','agQMove','Move down',`data-i="${i}" data-d="1"`,'xs')}${iconBtn('trash','agQRm','Remove',`data-i="${i}"`,'xs')}</td></tr>`).join('')}</tbody></table></div>${btn('Add question','agQAdd',{k:'sm',i:'plus'})}${fld('Information to collect',led('agcol',j.collect,'e.g. Service address'))}`,bdg(j.questions.length+' questions'))}
 ${acc('Outcomes','flow',`${fld('When disqualified',`<div class="choice">${['Send notification','Add tag','Add reason','Send follow-up','End conversation politely','Update database'].map(p=>`<button class="${j.whenDisq.includes(p)?'on':''}" data-act="agJT" data-k="whenDisq" data-v="${esc(p)}">${p}</button>`).join('')}</div>`,'The agent always updates the database at the end.')}${fld('If it can’t tell whether someone qualifies',`<div class="choice">${['Ask another qualifying question','Continue the conversation','Mark as “Needs review”','Transfer to a human','Disqualify','Stop qualification'].map(p=>`<button class="${j.cantDecide===p?'on':''}" data-act="agJS" data-k="cantDecide" data-v="${esc(p)}">${p}</button>`).join('')}</div>`)}`)}
 ${acc('Human handover','hand',`${fld('Hand over when',`<div class="choice">${['Customer asks for a human','Customer is angry','Customer requests a manager','Agent doesn’t know the answer','Required information can’t be obtained','Qualification is unclear'].map(p=>`<button class="${j.triggers.includes(p)?'on':''}" data-act="agJT" data-k="triggers" data-v="${esc(p)}">${p}</button>`).join('')}</div>`,'These go to “Assigned to me” with a notification.')}${fld('Who receives it',sel(['Sales team','Support team','Ali Raza (Manager)','Bilal Nasir (Owner)','Front desk'],j.handTo,'data-chg="agJob" data-k="handTo"','auto'))}`)}
 ${acc('Restrictions — never do this','lock',led('agres',j.restrict,'e.g. Never offer discounts'))}
 ${acc('Follow-up rules','refresh',`${led('agfr',j.follow,'e.g. First follow-up by email')}${btn('Open follow-up settings','agSec',{k:'sm',a:'data-v="follow"'})}`)}
 ${acc('How it talks','sms',`${fld('Conversation style',seg([['Professional','Professional'],['Friendly','Friendly'],['Casual','Casual']],j.tone,'agJS','data-k="tone"'))}${fld('Response style',sel(['Short and clear','Detailed','Very short (SMS style)','Match the customer'],j.style,'data-chg="agJob" data-k="style"','auto'))}${a.type==='sales'||a.type==='marketing'?fld('Sales posture',seg([['Salesperson','Salesperson'],['Consultative','Consultative'],['Direct','Direct'],['Neutral','Neutral']],j.posture,'agJS','data-k="posture"')):''}`)}
 ${acc('Compliance & sensitive information','shield',led('agcmp',j.compliance,'e.g. Never store card numbers'))}
 ${acc('Agent behaviour summary','spark',`<div class="banner ai small" style="display:block;line-height:1.6">${esc(a.name)} is a <b>${j.tone.toLowerCase()}</b>, <b>${j.posture.toLowerCase()}</b> ${AT[a.type].l.toLowerCase()} agent. Goal: <b>${esc(j.goal.toLowerCase())}</b>. It targets ${esc(j.target.toLowerCase())}${j.exclude.on?` (not ${esc(j.exclude.who.toLowerCase())})`:''}, sells ${esc(j.products.split('.')[0])}, asks ${j.questions.length} questions (${j.questions.filter(q=>q.req==='Required').length} required), and qualifies people when ${j.qual.filter(q=>q.imp==='Required').map(q=>esc(q.t.toLowerCase())).join(' and ')}. If unsure it will ${esc(j.cantDecide.toLowerCase())}. It hands over to ${esc(j.handTo)} when ${esc(j.triggers.slice(0,2).join(' or ').toLowerCase())}.</div>${aiBtn('Rewrite summary','toast','data-m="Summary refreshed" data-ai="1"','sm')}`,'',1)}`};
AGS.qa=a=>`<p class="muted">Exact answers for exact questions. “If the customer asks this → answer this.” Add a condition if the answer depends on something.</p>${a.qa.map((q,i)=>`<div class="card pad stack-s" style="padding:14px"><div class="row nw"><b class="small muted" style="width:120px">If customer asks</b><input class="in" value="${esc(q.q)}" data-chg="agQA" data-i="${i}" data-k="q"></div><div class="row nw"><b class="small muted" style="width:120px">Only when</b><input class="in" value="${esc(q.c||'')}" placeholder="Optional condition, e.g. customer is in Toronto" data-chg="agQA" data-i="${i}" data-k="c"></div><div class="row nw"><b class="small muted" style="width:120px">Answer</b><input class="in" value="${esc(q.a)}" data-chg="agQA" data-i="${i}" data-k="a">${iconBtn('trash','agQARm','Remove',`data-i="${i}"`,'xs')}</div></div>`).join('')}<div class="row">${btn('Add question & answer','agQAAdd',{k:'sm',i:'plus'})}${aiBtn('Suggest from real conversations','agQAAI','','sm')}</div>`;
AGS.know=a=>`<div class="row between"><p class="muted">Website links, folders, files, pictures and videos. Each “Add knowledge base” saves everything into one folder.</p><div class="row">${aiBtn('Create with AI','kbAI','','sm')}${btn('Add knowledge base','kbAdd',{k:'sm primary',i:'plus',a:'data-ctx="ag"'})}</div></div><div class="kbf">${a.kb.map((f,i)=>`<button class="fold ${S.ag.kbo===f.id?'sel':''}" data-act="kbOpen" data-id="${f.id}">${ic('folder',22)}<b>${esc(f.name)}</b><span class="small muted">${f.items.length} items · ${f.date}</span></button>`).join('')}</div>${(()=>{const f=a.kb.find(x=>x.id===S.ag.kbo);return f?`<div class="card"><div class="card-h"><h3>${ic('folder',14)} ${esc(f.name)}</h3><div class="row">${btn('Add to folder','kbAdd',{k:'xs',a:`data-ctx="ag" data-into="${f.id}"`})}${btn('Delete folder','kbDel',{k:'xs danger',a:`data-id="${f.id}"`})}</div></div>${f.items.map(it=>`<div class="lr">${ic({file:'file',link:'link',text:'edit',video:'video',image:'image'}[it.k],15)}<span class="m"><div class="t1">${esc(it.n)}</div><div class="t2">${esc(it.s)}</div></span>${bdg(ic('check',11)+'Learned','good')}</div>`).join('')}</div>`:''})()}`;
AGS.can=a=>{const cats=ACTIONS.concat(a.type==='tech'?[ACT_TECH]:[]).concat(a.type==='finance'?[ACT_FIN]:[]);
 return `<p class="muted">Turn on only what ${esc(a.name)} is allowed to do. Every action ends by updating your database.</p>${cats.map(([g,i,items])=>`<div class="catg"><div class="group-h">${ic(i,13)}${g}</div>${items.map(([k,l])=>optRow(l,k==='booking'?'Opens booking settings when turned on':k==='http'?`${a.http.length} actions set up`:'',`${k==='http'&&a.act.http?btn('Set up','httpList',{k:'xs'}):''}${k==='booking'&&a.act.booking?btn('Settings','bookingSettings',{k:'xs',a:'data-ctx="ag"'}):''}${sw(a.act[k],'agAct',`data-k="${k}"`)}`)).join('')}</div>`).join('')}
 ${a.act.http?`<div class="card"><div class="card-h"><h3>${ic('code',14)} HTTP actions</h3>${btn('Add HTTP action','httpNew',{k:'xs primary',i:'plus'})}</div>${a.http.map((h,i)=>`<button class="lr" data-act="httpEdit" data-i="${i}"><span class="bdg blue">${h.method}</span><span class="m"><div class="t1">${esc(h.name)}</div><div class="t2">${esc(h.url)}</div></span>${ic('right',14)}</button>`).join('')||'<p class="small muted" style="padding:12px 20px">No actions yet.</p>'}</div>`:''}
 ${a.type==='tech'?`<div class="card pad stack-s"><h3>Tech support settings</h3><div class="fgrid two">${fld('Ticketing system',sel(['Built-in tickets','Zendesk','Freshdesk','Jira Service Management'],'Built-in tickets'))}${fld('Status page URL','<input class="in" value="status.metromobile.example">')}${fld('Escalate to',`<input class="in" value="noc@metromobile.example">`)}${fld('Device list / manuals',btn('Add to knowledge','kbAdd',{k:'sm',a:'data-ctx="ag"'}))}</div></div>`:''}
 ${a.type==='finance'?`<div class="card pad stack-s"><h3>Finance settings</h3><div class="fgrid two">${fld('Payment provider',sel(['Stripe','Square','PayPal','Bank transfer only'],'Stripe'))}${fld('Invoice template',sel(['Standard','Detailed with tax lines','Minimal'],'Standard'))}${fld('Tax rate','<input class="in" value="13% HST (Ontario)">')}${fld('Reminder schedule',sel(['3 days before, on the day, 3 days after','Weekly until paid'],'3 days before, on the day, 3 days after'))}${fld('Refunds',sel(['Always need owner approval','Auto-approve under $25'],'Always need owner approval'))}${fld('Currencies',sel(['CAD $','USD $','PKR ₨','Multi-currency'],'CAD $'))}</div></div>`:''}`};
AGS.rules=a=>`${RULES.map(([g,i,items])=>`<div class="catg"><div class="group-h">${ic(i,13)}${g}</div>${items.map(([k,l])=>optRow(l,'',sw(a.rules[k],'agRule',`data-k="${k}"`))).join('')}</div>`).join('')}
 <div class="catg"><div class="group-h">${ic('percent',13)}Discounts</div>${optRow('Biggest discount allowed','',`<input type="range" min="0" max="30" value="${a.discount}" data-inp="agDisc" aria-label="Discount"><b class="num" id="agDiscV" style="width:40px">${a.discount}%</b>`)}</div>
 <div class="catg"><div class="group-h">${ic('transfer',13)}Handoff at a stage</div>${optRow('Hand off when a lead reaches a stage','',sw(a.handoff.on,'agHand'))}${a.handoff.on?`<div class="stack-s" style="padding-bottom:12px">${fld('At stage',sel(D.stages.telecom.out.map(s=>s.n).concat(['Submitted','Booked']),a.handoff.stage,'data-chg="agHandSt"','auto'))}<div class="choice">${[['same','Continue with the same agent'],['another','Assign to another agent'],['human','Assign to a human']].map(([v,l])=>`<button class="${a.handoff.mode===v?'on':''}" data-act="agHandM" data-v="${v}">${l}</button>`).join('')}</div>${a.handoff.mode==='another'?fld('Which agent',sel(D.agents.filter(x=>x.id!==a.id).map(x=>[x.id,x.name+' · '+AT[x.type].l]),a.handoff.to,'data-chg="agHandTo"','auto')):a.handoff.mode==='human'?fld('Which person',sel(D.team.map(t=>t[0]),'Ali Raza','','auto')):''}</div>`:''}</div>
 <div class="catg"><div class="group-h">${ic('users',13)}Who receives transfers</div>${optRow('Send handovers to',"They’re notified and it appears in Assigned to me",sel(['Sales team','Specific person: Ali Raza','Department: Support','Front desk'],'Sales team','','sm auto'))}</div>`;
AGS.follow=a=>fuHTML('ag','Campaign follow-up settings <b>override</b> these for that campaign.');
AGS.booking=a=>`${optRow(`${ic('calendar',14)} ${esc(a.name)} books appointments`,'Services, capacity, hours, reminders, self-booking page and calendar sync',`${a.booking?btn('Booking settings','bookingSettings',{k:'sm',a:'data-ctx="ag"'}):''}${sw(a.booking,'agBooking')}`)}<div class="banner">${ic('bell',15)}<span class="small"><b>Receptionist auto-takeover:</b> in any campaign, if a customer asks for an appointment, the receptionist (Rhea) steps in — even if she wasn’t assigned. You get a notification in Assigned to me and inside the chat.</span></div>${a.booking?`<div class="card pad stack-s"><h3>Services ${esc(a.name)} can book</h3>${(D.services.k3).map(s=>optRow(esc(s.n),`${s.dur} min · ${esc(s.staff)} · ${s.price?money(s.price):'Free'}`,sw(true,'noop'))).join('')}</div>`:''}`;

/* ---------- review & test panels ---------- */
const AGSUG={s3:[['bad','Your qualifying criteria are not clear — 2 of 4 are “Optional”.','job'],['warn','Sounds too pushy in sales: 3 offers in the first minute.','overview'],['good','Knowledge base covers 91% of real questions.','know']]};
function agSug(a){return AGSUG[a.id]||(a.score>80?[['good','Instructions follow the standard structure.','instr'],['good','Knowledge answers 94% of real questions.','know'],['warn','Add a Q&A for “Can I keep my number?”','qa']]:[['bad','Missing: what happens when the customer is not eligible.','job'],['warn','Style on texts is long for SMS — keep it to 1–2 sentences.','overview'],['warn','No follow-ups for inbound leads yet.','follow']])}
function agReview(a){return `<div class="card"><div class="card-h"><h3>${ic('spark',14)} Review</h3>${btn('Re-run','agRerun',{k:'xs ghost',i:'refresh'})}</div><div class="card-b stack"><div class="review">${ring(a.score,a.score+'%',a.score>84?'var(--good)':a.score>70?'var(--warn)':'var(--bad)')}<div><b>${a.score>84?'Good to go':a.score>70?'Almost there':'Needs work'}</b><div class="small muted">How optimized ${esc(a.name)}’s prompt and instructions are — from your answers, test chats and real conversations.</div></div></div><div class="sugl">${agSug(a).map(s=>`<div class="sugi ${s[0]}">${ic(s[0]==='good'?'check':'alert',14)}<span class="grow">${s[1]}</span>${s[0]!=='good'?btn('Fix','agFix',{k:'xs',a:`data-sec="${s[2]}"`}):''}</div>`).join('')}</div>${aiBtn('Optimize everything with AI','agOptAll','','sm')}</div></div>`}
function agTest(a){const log=S.ag.test[a.id]||(S.ag.test[a.id]=[{w:'a',t:agGreet(a)}]);
 return `<div class="card testp"><div class="card-h"><h3>Test / preview</h3>${seg([['chat','Text','sms'],['voice','Voice message','mic'],['call','Call','phone']],S.ag.tmode,'agTMode')}</div><div class="tlog" id="tlog">${log.map(m=>m.w==='tool'?`<div class="tool">${ic('spark',12)}<span>${m.t}</span></div>`:m.w==='hint'?`<div class="hint">${ic('alert',13)}<span class="grow">${m.t}</span>${btn('Fix','agFix',{k:'xs',a:`data-sec="${m.sec}"`})}</div>`:m.w==='typing'?`<div class="typing"><i></i><i></i><i></i></div>`:`<div class="tmsg ${m.w==='u'?'me':''}">${m.v?ic('mic',12)+' ':''}${esc(m.t)}</div>`).join('')}</div>
 <div style="padding:8px 10px 0" class="sugg">${(a.type==='reception'?['Anything Tuesday?','How much is whitening?','I want a person']:a.type==='tech'?['My internet is down','Restart my modem','Talk to a person']:a.type==='finance'?['Why is my bill higher?','Send my invoice','Payment plan?']:['How much for 3 lines?','OK, go ahead','STOP']).map(s=>`<button data-act="agTQ" data-t="${esc(s)}">${esc(s)}</button>`).join('')}</div>
 <div class="row nw" style="padding:10px">${S.ag.tmode==='call'?btn('Start test call','agTCall',{k:'primary',i:'phone',a:'style="flex:1"'}):S.ag.tmode==='voice'?btn('Hold to record a voice message','agTVoice',{k:'',i:'mic',a:'style="flex:1"'}):`<input class="in" id="tIn" placeholder="Write as a customer…" data-enter="agTSend" aria-label="Test message">${micBtn('#tIn','Hi, how much is it for three lines?')}${btn('','agTSend',{k:'primary icon',i:'send',lbl:'Send'})}`}${btn('','agTReset',{k:'icon ghost',i:'refresh',lbl:'Restart test',t:'Restart test'})}</div></div>`}
const agGreet=a=>a.type==='reception'?`Hi! This is ${a.name}, BrightSmile Dental’s AI assistant. How can I help?`:a.type==='tech'?`Hi, I’m ${a.name} from Metro Mobile tech support. What’s going on?`:a.type==='finance'?`Hi, I’m ${a.name} from Metro Mobile billing. How can I help with your account?`:a.type==='support'?`Hi, ${a.name} here from Metro Mobile support. What can I help with?`:`Hi Maria, it’s ${a.name} from Metro Mobile. Internet 1 Gig is $50/month with free installation this month. Want me to check your street?`;
function agReply(a,t){t=t.toLowerCase();const ctx=S.ag.ctx=S.ag.ctx||{};
 if(/\bstop\b|unsubscribe|remove me/.test(t))return {tools:['opt_out(all channels) → added to Do-Not-Contact','update_database()'],r:'Understood — you won’t hear from us again. Take care!'};
 if(/person|human|manager|angry/.test(t))return {tools:['transfer_to_human(reason: "asked for a person") → Ali Raza notified','add_comment("Customer asked for a person during test")'],r:'Of course — I’m passing you to Ali on our team. He’ll reply here in a few minutes.'};
 if(a.type==='tech'&&/down|not working|slow|restart|modem/.test(t))return {tools:['http: Check service status (GET /v1/status?address=214 King St W) → no outage','http: Restart modem (POST /v1/modem/restart) → 200 OK','update_stage(Resolved)'],r:'There’s no outage on your street, so I restarted your modem remotely. Give it 2 minutes — is it working now?'};
 if(a.type==='finance'&&/bill|invoice|higher|payment|plan/.test(t))return {tools:['lookup_invoice(#INV-2291) → $124.99 (roaming $24.99)','create_payment_plan? (needs approval)'],r:'Your bill is $124.99 this month because of a $24.99 roaming charge on Aug 14. I can email your invoice, or ask a manager to review the charge. Which would you like?'};
 if(/price|cost|how much|whitening/.test(t))return a.type==='reception'?{tools:['search_knowledge("whitening") → Price list 2026.pdf p.3'],r:'Whitening is $350 and takes about an hour with Dr. Lee. Shall I find you a time?'}:{tools:['search_knowledge("price 3 lines") → $35/line','create_quote(3 × 5G Unlimited) → $105/mo'],r:'3 lines on 5G Unlimited is $105 a month, taxes included, and your internet bill drops by $10. Shall I set it up?'};
 if(ctx.offered&&/\d|morning|afternoon|first|works/.test(t)){ctx.offered=false;return {tools:['book(Tue Sep 29, 4:00 PM, Dr. Khan) → slot locked ✓','update_stage(Appointment Booked)','send_sms(confirmation)'],r:'You’re booked for Tuesday at 4:00 PM with Dr. Khan. I’ve texted you a confirmation.'}}
 if(a.type==='reception'&&/tuesday|book|appointment|anything|time/.test(t)){ctx.offered=true;return {tools:['check_availability(Tue Sep 29) → 10:30 AM, 2:00 PM, 4:00 PM'],r:'On Tuesday I have 10:30 AM, 2:00 PM or 4:00 PM. Which works best?'}}
 if(/ok|go ahead|yes|sure|interested/.test(t))return {tools:['update_stage(Interested → Order Booked)','create_order(3 lines) → #48219','update_contact(plan: 5G Unlimited × 3)','add_comment("Booked in test")'],r:'Done! Order #48219 is booked and your SIMs ship Saturday. Anything else I can help with?'};
 return {tools:['search_knowledge("'+t.slice(0,28)+'") → 2 matches'],r:a.type==='reception'?'Happy to help. Is this for a check-up, a cleaning or something else?':'Good question! How many people would use the plan at home?'}}
function agTestSend(text,voice){const a=agent(S.ag.sel),log=S.ag.test[a.id];log.push({w:'u',t:text,v:voice});log.push({w:'typing'});rrTest();setTimeout(()=>{log.pop();const r=agReply(a,text);r.tools.forEach(x=>log.push({w:'tool',t:esc(x)}));log.push({w:'a',t:r.r});const n=log.filter(m=>m.w==='u').length;if(n===2&&agSug(a)[0][0]!=='good')log.push({w:'hint',t:'AI noticed: '+agSug(a)[0][1],sec:agSug(a)[0][2]});rrTest()},650)}
function rrTest(){const a=agent(S.ag.sel);const p=$('.testp');if(p){p.outerHTML=agTest(a);const l=$('#tlog');l.scrollTop=l.scrollHeight;const i=$('#tIn');if(i)i.focus()}}
A.agTSend=()=>{const i=$('#tIn');const v=(i&&i.value||'').trim();if(v)agTestSend(v)};
A.agTQ=el=>agTestSend(el.dataset.t);
A.agTMode=el=>{S.ag.tmode=el.dataset.v;rrTest()};
A.agTReset=()=>{const a=agent(S.ag.sel);S.ag.test[a.id]=[{w:'a',t:agGreet(a)}];S.ag.ctx={};rrTest()};
A.agTVoice=el=>{el.classList.add('rec');toast('Recording… (prototype sample)',true);setTimeout(()=>{el.classList.remove('rec');agTestSend(agent(S.ag.sel).type==='reception'?'Hi, do you have anything on Tuesday for a cleaning?':'Hi, how much would it be for three lines?',true)},1400)};
A.agTCall=()=>{const a=agent(S.ag.sel),log=S.ag.test[a.id];const lines=[['a',agGreet(a)],['u','Hi, yes — tell me more.'],['a',a.type==='reception'?'Of course! Are you looking for a check-up or a cleaning?':'Sure. Do you have home internet right now, and who with?'],['u',a.type==='reception'?'A cleaning, Tuesday if possible.':'Yes, Bell, about $85 a month.'],['a',a.type==='reception'?'I have Tuesday at 2 PM or 4 PM. Which is better?':'You’d save $35 a month with us. Shall I book the installation?']];log.push({w:'tool',t:'Test call started · voice: '+esc(a.voice)});rrTest();let i=0;const t=setInterval(()=>{if(i>=lines.length||S.view!=='agents'){clearInterval(t);if(S.view==='agents'){log.push({w:'tool',t:'Call ended · 1m 04s · summary saved'});rrTest()}return}log.push({w:lines[i][0],t:lines[i][1],v:lines[i][0]==='u'});i++;rrTest()},1100)};
A.agFix=el=>{S.ag.sec=el.dataset.sec;rr();toast('Here’s where to fix it')};
A.agRerun=()=>{const a=agent(S.ag.sel);a.score=Math.min(97,a.score+rint(1,4));rr();toast('Review updated',true)};
A.agOptAll=()=>{const a=agent(S.ag.sel);openM('gsAIRun',{i:0,n:0,lines:['Clarified qualifying criteria (2 made Required)','Softened sales posture on calls','Added 3 Q&A pairs from real conversations','Added inbound follow-ups','Saved as version '+(a.ver+1)]});const t=setInterval(()=>{if(!S.modal||S.modal.t!=='gsAIRun'){clearInterval(t);return}S.modal.n++;if(S.modal.n>=S.modal.lines.length){clearInterval(t);a.score=Math.max(a.score,89);a.ver++;a.versions.push({v:a.ver,label:'Optimized by AI',date:'Sep 27'});a.edited=true;if(S.view==='agents')rr()}renderModal()},600)};

/* ---------- editor actions ---------- */
const curA=()=>agent(S.ag.sel);
I.agV=el=>{curA()[el.dataset.k]=el.value};I.agJ=el=>{curA().job[el.dataset.k]=el.value};I.agSty=el=>{curA().style[el.dataset.k]=el.value};I.agEx=el=>{curA().job.exclude.who=el.value};
I.agDisc=el=>{curA().discount=+el.value;const v=$('#agDiscV');if(v)v.textContent=el.value+'%'};
C.agType2=el=>{const a=curA();a.type=el.value;S.ag.type=el.value;rr();toast(a.name+' is now a '+AT[el.value].l+' agent')};
A.agMode=el=>{const a=curA();if(a.mode===el.dataset.v)return;openM('agRename',{mode:el.dataset.v,name:a.name})};
M.agRename=m=>MS('Rename the agent',`<p class="muted">You’re switching ${esc(curA().name)} to a <b>${m.mode.toLowerCase()}</b>. Give it a new name so nobody confuses the two.</p>${fld('New name',`<input class="in" id="rnN" value="${esc(m.name+' '+(m.mode==='Chat agent'?'(chat)':'(voice)'))}" data-autofocus>`)}`,`${btn('Cancel','close',{k:'ghost'})}${btn('Rename & switch','agRenameGo',{k:'primary'})}`,'n');
A.agRenameGo=()=>{const a=curA(),n=$('#rnN').value.trim();if(!n||n===a.name){toast('Please choose a different name');return}a.name=n;a.mode=S.modal.mode;a.edited=true;closeM();rr();toast('Switched and renamed to '+n)};
A.agDir=el=>{curA().dir=el.dataset.v;rr()};
A.agLang=el=>{const a=curA().langs,v=el.dataset.v,i=a.indexOf(v);i<0?a.push(v):a.length>1&&a.splice(i,1);rr()};
C.agVoice=el=>{curA().voice=el.value;toast('Voice changed')};
A.agStatus=el=>{const a=curA();if(el.dataset.v==='live'&&a.needsInfo){openM('gate');return}a.status=el.dataset.v;rr()};
C.agTpl=el=>{curA().template=el.value;toast('Template selected — press “Use as it is” or edit')};
C.agJob=el=>{curA().job[el.dataset.k]=el.value};
A.agJS=el=>{curA().job[el.dataset.k]=el.dataset.v;rr()};
A.agJT=el=>{const a=curA().job[el.dataset.k],v=el.dataset.v,i=a.indexOf(v);i<0?a.push(v):a.splice(i,1);rr()};
A.agExcl=el=>{curA().job.exclude.on=el.checked;rr()};
A.agPricePic=()=>openM('aiNote',{title:'AI read your price list picture',body:`<p>Here’s what I understood from <b>pricing.jpg</b> — <b>is this correct?</b></p><ul><li>Phone line — $20 / month</li><li>Internet 1 Gig — $50 / month</li><li>TV package — $10 / month</li><li>5G Unlimited — $35 per line / month</li><li>Taxes included · free installation this month</li></ul><div class="row">${btn('Yes, correct','close',{k:'sm primary'})}${btn('Change something','close',{k:'sm'})}</div>`});
C.agQ=el=>{curA().job.questions[+el.dataset.i][el.dataset.k]=el.value};
A.agQMove=el=>{const q=curA().job.questions,i=+el.dataset.i,j=i+ +el.dataset.d;if(j<0||j>=q.length)return;[q[i],q[j]]=[q[j],q[i]];rr()};
A.agQRm=el=>{curA().job.questions.splice(+el.dataset.i,1);rr()};A.agQAdd=()=>{curA().job.questions.push({q:'New question',req:'Optional',att:'Once',cond:''});rr()};
C.agQA=el=>{curA().qa[+el.dataset.i][el.dataset.k]=el.value};A.agQARm=el=>{curA().qa.splice(+el.dataset.i,1);rr()};A.agQAAdd=()=>{curA().qa.push({q:'',a:'',c:''});rr()};
A.agQAAI=()=>{curA().qa.push({q:'Is there a contract?',a:'No contract — cancel anytime.'},{q:'How long is installation?',a:'About 2 hours. A technician comes to your home.'});rr();toast('Added 2 Q&A from real conversations',true)};
A.agAct=el=>{const a=curA();a.act[el.dataset.k]=el.checked;if(el.dataset.k==='booking'){a.booking=el.checked;if(el.checked)openM('bookingSettings',{ctx:'ag',camp:'k3'})}if(el.dataset.k==='http'){rr();if(el.checked&&!a.http.length)A.httpNew()}};
A.agRule=el=>{curA().rules[el.dataset.k]=el.checked};
A.agHand=el=>{curA().handoff.on=el.checked;rr()};C.agHandSt=el=>{curA().handoff.stage=el.value};A.agHandM=el=>{curA().handoff.mode=el.dataset.v;rr()};C.agHandTo=el=>{curA().handoff.to=el.value};
A.agBooking=el=>{const a=curA();a.booking=el.checked;a.act.booking=el.checked;rr();if(el.checked)openM('bookingSettings',{ctx:'ag',camp:'k3'})};
