M.agAnalyze=m=>{const a=agent(m.id);return MS(`${ic('spark',16)} AI analysis · ${esc(a.name)}`,`<div class="kpis">${kpi('Conversations read',nf(a.ws.msgs/4))}${kpi('Calls listened',nf(a.ws.calls/4))}${kpi('Success rate',a.ws.success+'%')}${kpi('Review score',a.score+'%')}</div><div class="grid g2"><div class="card pad stack-s"><h3>What’s going wrong</h3><div class="sugl">${agSug(a).filter(s=>s[0]!=='good').map(s=>`<div class="sugi ${s[0]}">${ic('alert',14)}<span>${s[1]}</span></div>`).join('')}<div class="sugi warn">${ic('alert',14)}<span>Asks for the address before explaining the offer (22% stop replying).</span></div></div></div><div class="card pad stack-s"><h3>What works</h3><div class="sugl"><div class="sugi good">${ic('check',14)}<span>Evening calls (4–8 PM) book 2× more.</span></div><div class="sugi good">${ic('check',14)}<span>Mentioning “keep your number” lifts replies 9%.</span></div></div></div></div>`,`${btn('Save to Reports','anSave',{k:'',a:'data-k="k1"'})}${aiBtn('Fix it for me','agOptAll')}`,'w')};
