A.httpList=()=>{S.ag.sec='can';rr()};
A.httpNew=()=>openM('http',{i:-1,h:{name:'',prompt:'',method:'GET',url:'https://',params:[['','']],headers:[['Authorization','Bearer ']],fields:[],body:'',auth:'Bearer token'},res:null});
A.httpEdit=el=>openM('http',{i:+el.dataset.i,h:clone(curA().http[+el.dataset.i]),res:null});
M.http=m=>{const h=m.h;const kv=(k,rows)=>`<div class="stack-s">${rows.map((r,i)=>`<div class="row nw"><input class="in sm" value="${esc(r[0])}" placeholder="Key" data-chg="httpKV" data-k="${k}" data-i="${i}" data-j="0"><input class="in sm" value="${esc(r[1])}" placeholder="Value — use {contact.phone} etc." data-chg="httpKV" data-k="${k}" data-i="${i}" data-j="1">${iconBtn('x','httpKVRm','Remove',`data-k="${k}" data-i="${i}"`,'xs')}</div>`).join('')}${btn('Add','httpKVAdd',{k:'xs ghost',i:'plus',a:`data-k="${k}"`})}</div>`;
 return MS('HTTP action',`<div class="fgrid two">${fld('Action name',`<input class="in" value="${esc(h.name)}" placeholder="e.g. Check service status" data-chg="httpV" data-k="name">`)}${fld('Authentication',sel(['None','Bearer token','API key in header','Basic auth','OAuth 2.0'],h.auth||'Bearer token','data-chg="httpV" data-k="auth"'))}</div>
 ${fld('When should the agent use it? (prompt)',`<textarea class="in" data-chg="httpV" data-k="prompt" placeholder="e.g. Use when a customer says their internet is down, to check for an outage at their address.">${esc(h.prompt)}</textarea>`)}
 ${fld('Information the agent must collect first (fields)',led('httpf',h.fields,'e.g. address'))}
 <div class="row nw">${sel(['GET','POST','PUT','PATCH','DELETE'],h.method,'data-chg="httpV" data-k="method" style="width:110px"')}<input class="in" value="${esc(h.url)}" data-chg="httpV" data-k="url" aria-label="URL"></div>
 <div class="grid g2"><div>${fld('Query parameters',kv('params',h.params))}</div><div>${fld('Headers',kv('headers',h.headers))}</div></div>
 ${h.method!=='GET'?fld('Body (JSON)',`<textarea class="in mono" data-chg="httpV" data-k="body">${esc(h.body||'{\n  "account_id": "{contact.custom.account_id}"\n}')}</textarea>`):''}
 <div class="fgrid three">${fld('Timeout',sel(['5 seconds','10 seconds','30 seconds'],'10 seconds'))}${fld('If it fails',sel(['Tell the customer and hand over','Try again once','Continue without it'],'Tell the customer and hand over'))}${fld('Save response to',sel(['Nothing','Contact field','Comment on the conversation'],'Comment on the conversation'))}</div>
 <div class="row">${btn('Send test request','httpTest',{k:'sm',i:'play'})}${m.res?`<span class="bdg good">200 OK · 184 ms</span>`:''}</div>${m.res?`<div class="card pad mono" style="white-space:pre;overflow-x:auto;font-size:12px">{\n  "address": "214 King St W",\n  "outage": false,\n  "last_check": "2026-09-27T21:04:11Z"\n}</div>`:''}`,`${m.i>=0?btn('Delete','httpDel',{k:'danger ghost'}):''}${btn('Cancel','close',{k:'ghost'})}${btn('Save action','httpSave',{k:'primary'})}`,'w')};
C.httpV=el=>{S.modal.h[el.dataset.k]=el.value;if(el.dataset.k==='method')renderModal()};
C.httpKV=el=>{S.modal.h[el.dataset.k][+el.dataset.i][+el.dataset.j]=el.value};
A.httpKVAdd=el=>{S.modal.h[el.dataset.k].push(['','']);renderModal()};A.httpKVRm=el=>{S.modal.h[el.dataset.k].splice(+el.dataset.i,1);renderModal()};
A.httpTest=()=>{S.modal.res=1;renderModal()};
A.httpSave=()=>{const m=S.modal,a=curA();if(!m.h.name){toast('Give the action a name');return}if(m.i>=0)a.http[m.i]=m.h;else a.http.push(m.h);a.act.http=true;closeM();rr();toast('HTTP action saved')};
A.httpDel=()=>{curA().http.splice(S.modal.i,1);closeM();rr()};

