A.agCreate=el=>openM('agCreate',{step:0,type:S.ag.type,base:D.agents.find(a=>a.type===S.ag.type).id,name:'',desc:'',blank:!!(el&&el.dataset&&el.dataset.blank)});
M.agCreate=m=>{if(m.step===2)return MS('Creating your agent',`<div class="creating"><div class="cr-orb"><span class="in2">${ic(AT[m.type].i,30)}</span></div><h2>Creating ${esc(m.name||'your agent')}…</h2><div class="crsteps">${['Copying the '+AT[m.type].l+' core (hidden, by Crewline)','Setting voice and personality','Connecting tools: calls, texts, email, stages','Writing your business layer','Running a first review'].map((s,i)=>`<div class="${i<m.n?'dn':''}">${i<m.n?`<span class="ok">${ic('check',11)}</span>`:i===m.n?'<span class="spin"></span>':'<span style="width:18px"></span>'}${s}</div>`).join('')}</div></div>`,'','');
 return MS('New agent',`<div class="stack"><div class="lbl">1 · Agent type</div><div class="atypes" style="margin:0">${Object.entries(AT).map(([k,v])=>`<button class="atype ${m.type===k?'on':''}" data-act="acType" data-v="${k}"><span class="ico">${ic(v.i,15)}</span><span class="trunc"><b>${v.l}</b></span></button>`).join('')}</div>
 <div class="lbl">2 · Start from</div><div class="choice">${D.agents.filter(a=>a.type===m.type).map(a=>`<button class="${m.base===a.id&&!m.blank?'on':''}" data-act="acBase" data-v="${a.id}">${a.name} · ${esc(a.voice.split('·')[1]||'')}</button>`).join('')}<button class="${m.blank?'on':''}" data-act="acBase" data-v="">Blank ${AT[m.type].l.toLowerCase()} agent</button></div>
 <div class="fgrid two">${fld('3 · Name','<input class="in" id="acN" placeholder="e.g. Zara" value="'+esc(m.name)+'" data-inp="acN">')}${fld('Voice',sel(D.voices.map(v=>v[0]+' · '+v[1]),'Sarah · Warm female · US','id="acV"'))}</div>
 ${fld('4 · Describe the job (optional) — type or speak',`<textarea class="in" id="acD" data-inp="acD" placeholder="e.g. Answer calls for my restaurant, take reservations up to 8 people, tell people today’s specials">${esc(m.desc)}</textarea><div class="row">${micBtn('#acD','Answer calls for my restaurant, take table reservations up to 8 people and tell people about our specials')}</div>`)}</div>`,`${btn('Cancel','close',{k:'ghost'})}${btn('Create agent','acGo',{k:'primary',i:'spark'})}`,'w')};
A.acType=el=>{S.modal.type=el.dataset.v;S.modal.base=D.agents.find(a=>a.type===el.dataset.v).id;renderModal()};
A.acBase=el=>{S.modal.blank=!el.dataset.v;S.modal.base=el.dataset.v;renderModal()};
I.acN=el=>{S.modal.name=el.value};I.acD=el=>{S.modal.desc=el.value};
A.acGo=()=>{const m=S.modal;if(!m.name.trim()){toast('Give your agent a name');return}const base=m.blank?D.agents.find(a=>a.type===m.type):agent(m.base);const voice=$('#acV').value;
 const a=Object.assign(clone(base),{id:uid('ag'),name:m.name.trim(),voice,camps:[],status:'ready',edited:true,ver:1,versions:[{v:1,label:'Created by you',date:'Sep 27'}],score:m.blank?52:66,needsInfo:true,ws:Object.fromEntries(Object.keys(base.ws).map(k=>[k,0]))});if(m.blank){a.job.qual=[];a.job.disq=[];a.job.products='';a.job.pricing=''}if(m.desc)a.instr=`Your job: ${m.desc}.\nKeep replies short and friendly. Confirm details back to the customer.`;
 m.step=2;m.n=0;renderModal();const t=setInterval(()=>{if(!S.modal||S.modal.t!=='agCreate'){clearInterval(t);return}S.modal.n++;renderModal();if(S.modal.n>=5){clearInterval(t);setTimeout(()=>{D.agents.push(a);S.ag.type=a.type;S.ag.sel=a.id;S.ag.sec='overview';S.ag.view='tiles';go('agents');openM('gate')},400)}},550)};

/* ---------- guided builder chat (Create / edit with AI) ---------- */
const BQ=[
 {k:'stages',q:'Let’s start with <b>stages</b> — where leads sit as the agent talks. Which stages should it use?',o:[['telecom','Telecom (New → Installed)'],['realestate','Real estate (New → Closed)'],['dental','Dental (Requested → Completed)'],['ai','Build them from my business']]},
 {k:'script',q:'Do you have a <b>script</b> you want it to follow? Paste it, say it, or skip.',free:1,skip:1,sample:'Greet them, say we are Metro Mobile, mention internet for 50 dollars with free installation, ask who their provider is.'},
 {k:'kb',q:'Now your <b>knowledge base</b>. Attach price lists, FAQs or brochures with the 📎 button — or I can create it from your website.',o:[['upload','I attached files'],['ai','Create it with AI from my website'],['skip','Skip for now']]},
 {k:'purposes',q:'What is the agent’s <b>primary purpose</b>? Pick all that apply.',multi:1,o:['Generate leads','Qualify leads','Sell products','Book appointments','Schedule installation','Follow up with leads','Reactivate old leads','Upsell existing customers','Cross-sell products','Collect customer information','Transfer qualified leads to a human','Other'].map(x=>[x,x])},
 {k:'goal',q:'What’s the <b>main goal</b> of each conversation?',o:['Qualify the lead','Make the sale','Book an appointment','Generate a callback','Transfer to a human'].map(x=>[x,x])},
 {k:'target',q:'Who are you <b>targeting</b>?',o:[['Individuals','Individuals'],['Businesses','Businesses'],['Both','Both']]},
 {k:'exclude',q:'Is there anyone you <b>don’t</b> want to target?',free:1,skip:1,sample:'People under 18 and existing business customers'},
 {k:'products',q:'What <b>products</b> are you selling?',free:1,sample:'Home internet, TV packages and mobile phone lines'},
 {k:'pricing',q:'What’s the <b>pricing</b>? Type it, say it, or attach a picture of your price list.',free:1,sample:'Phone line 20 a month, internet 50 a month, TV 10 a month, taxes included'},
 {k:'billing',q:'How are customers <b>billed</b>?',o:[['One-time','One-time'],['Monthly','Monthly'],['Annual','Annual']],skipFor:['reception']},
 {k:'qual',q:'What makes someone a <b>qualified</b> lead? Just talk — I’ll turn it into a list.',free:1,sample:'They live in Mississauga or Toronto, they are the account holder, and they pay more than 60 dollars today'},
 {k:'disq',q:'What <b>disqualifies</b> someone?',free:1,sample:'Outside our area, under 18, or locked in a contract for more than 6 months'},
 {k:'questions',q:'Which <b>questions</b> should it ask, and what <b>information</b> should it collect?',free:1,sample:'Do you have internet now, who is your provider, how much do you pay, what is your address, best day for installation'},
 {k:'attempts',q:'If someone avoids a question, how many times should it <b>ask again</b>?',o:[['Once','Once'],['Twice','Twice'],['Three times','Three times'],['Until answered','Until answered']]},
 {k:'cant',q:'If it <b>can’t tell</b> whether someone qualifies, what should it do?',o:['Ask another qualifying question','Continue the conversation','Mark as “Needs review”','Transfer to a human','Disqualify'].map(x=>[x,x])},
 {k:'hand',q:'When should it <b>hand over to a person</b>?',multi:1,o:['Customer asks for a human','Customer is angry','Customer requests a manager','Agent doesn’t know the answer','Qualification is unclear'].map(x=>[x,x])},
 {k:'restrict',q:'What must it <b>never</b> do?',free:1,sample:'Never change prices, never give discounts above 10 percent, never promise installation dates'},
 {k:'tone',q:'How should it <b>talk</b>?',o:[['Professional','Professional'],['Friendly','Friendly'],['Casual','Casual']]},
 {k:'posture',q:'And its <b>sales style</b>?',o:[['Consultative','Consultative'],['Salesperson','Salesperson'],['Direct','Direct'],['Neutral','Neutral']],skipFor:['reception','support','tech','finance']},
];
const splitList=t=>t.split(/,|;|\.|\band\b|\bor\b/i).map(s=>s.trim()).filter(s=>s.length>2).map(s=>s[0].toUpperCase()+s.slice(1));
A.openBuilder=el=>{closeM();const ctx=el.dataset.ctx||'agent';const a=ctx==='agent'?curA():null;const qs=BQ.filter(q=>!(q.skipFor&&a&&q.skipFor.includes(a.type)));openM('builder',{ctx,qs,i:0,ans:{},msgs:[{r:'x',h:`Hi! I’ll set up ${a?'<b>'+esc(a.name)+'</b>':'this campaign'} with you. I’ll ask one thing at a time and write back what I understood — you can talk or type. I’ll skip anything that doesn’t apply to your business.`}]});bAsk()};
function bAsk(){const m=S.modal;const q=m.qs[m.i];if(!q){const a=m.ctx==='agent'?curA():null;m.msgs.push({r:'x',h:`That’s everything. <b>Here’s how ${a?esc(a.name):'your agents'} will behave:</b><div class="ccard"><div class="b">Goal: <b>${esc(m.ans.goal||'Make the sale')}</b> · Targets ${esc((m.ans.target||'Individuals').toLowerCase())} · Sells ${esc(m.ans.products||'your products')} · Qualifies when ${esc((m.ans.qual||[]).slice(0,2).join(' and ')||'criteria are met').toLowerCase()} · If unsure: ${esc((m.ans.cant||'Mark as “Needs review”').toLowerCase())} · Tone: ${esc((m.ans.tone||'Friendly').toLowerCase())}.</div></div>`,o:{k:'__done',items:[['save','Save to '+(a?a.name:'campaign')],['review','Let me review the fields first']]}});renderModal();return}
 m.msgs.push({r:'x',h:`<span class="small faint">Question ${m.i+1} of ${m.qs.length}</span><br>${q.q}`,o:q.o?{k:q.k,multi:q.multi,items:q.o,sel:[]}:null,free:q.free,skip:q.skip});renderModal()}
M.builder=m=>{const q=m.qs[m.i];return `<div class="mb" data-act="bgclose"><div class="modal w" style="height:calc(100dvh - 48px)" role="dialog" aria-modal="true" aria-label="Create with AI"><div class="mh"><div class="row"><span class="orb" style="width:32px;height:32px;border-radius:9px">${ic('spark',16)}</span><div><h2>${m.ctx==='agent'?'Create / edit '+esc(curA().name)+' with AI':'Campaign details with AI'}</h2><div class="small muted">Build order: stages → script → knowledge → questions</div></div></div><div class="row">${ring(Math.round(m.i/m.qs.length*100),Math.round(m.i/m.qs.length*100)+'%')}<button class="btn icon ghost sm" data-act="close" aria-label="Close">${ic('x',16)}</button></div></div>
 <div class="mbd" id="blog" style="background:var(--subtle-2)"><div class="chat">${m.msgs.map((x,mi)=>x.r==='u'?`<div class="cm u"><div class="bb">${esc(x.h)}</div></div>`:`<div class="cm x">${MXI()}<div class="bb">${x.h}${x.o?`<div class="opts ${x.o.done?'done':''}">${x.o.items.map(([v,l])=>`<button class="${(x.o.sel||[]).includes(v)?'on':''}" data-act="bOpt" data-m="${mi}" data-v="${esc(v)}">${esc(l)}</button>`).join('')}${x.o.multi&&!x.o.done?`<button data-act="bOpt" data-m="${mi}" data-v="__go" style="background:var(--primary);color:#fff;border-color:var(--primary)">Continue</button>`:''}</div>`:''}${x.skip&&mi===m.msgs.length-1?`<div class="opts"><button data-act="bSkip">Skip this</button></div>`:''}</div></div>`).join('')}</div></div>
 <div class="mf2" style="display:block">${aiBox('bIn',q&&q.free?'Type or press the mic and just talk…':'Type anything — or pick an option above','bSend',{sample:q&&q.sample||'Yes, that is correct'})}</div></div></div>`};
AFTER.__b=()=>{};
const _rm=renderModal;renderModal=function(){_rm();const l=$('#blog');if(l)l.scrollTop=l.scrollHeight};
A.bOpt=el=>{const m=S.modal,x=m.msgs[+el.dataset.m],o=x.o,v=el.dataset.v;if(o.done)return;
 if(o.k==='__done'){o.done=true;o.sel=[v];if(v==='save'){bApply();return}closeM();S.ag.sec='job';rr();return}
 if(o.k==='__verify'){o.done=true;o.sel=[v];m.msgs.push({r:'u',h:v==='yes'?'Yes, correct':'Let me change it'});if(v==='yes'){m.i++;bAsk()}else{m.msgs.push({r:'x',h:'No problem — say it again the way you want it.'});renderModal()}return}
 if(o.multi&&v!=='__go'){o.sel=o.sel||[];const i=o.sel.indexOf(v);i<0?o.sel.push(v):o.sel.splice(i,1);renderModal();return}
 if(o.multi){if(!o.sel.length){toast('Pick at least one');return}o.done=true;m.ans[o.k]=o.sel.slice();m.msgs.push({r:'u',h:o.sel.join(', ')});m.i++;bAsk();return}
 o.done=true;o.sel=[v];const lbl=(o.items.find(x=>x[0]===v)||[,v])[1];m.ans[o.k]=v;m.msgs.push({r:'u',h:lbl});
 if(o.k==='kb'&&v==='ai')m.msgs.push({r:'x',h:'Done — I read <b>metromobile.example</b> (31 pages) and made a knowledge folder. You can check it later under “What they know”.'});
 if(o.k==='stages'&&v==='ai')m.msgs.push({r:'x',h:'I’ll build stages from your answers at the end and show them to you.'});
 m.i++;bAsk()};
A.bSkip=()=>{const m=S.modal;m.msgs.push({r:'u',h:'Skip'});m.i++;bAsk()};
A.bSend=()=>{const i=$('#bIn'),t=(i.value||'').trim();if(!t)return;const m=S.modal,q=m.qs[m.i];m.msgs.push({r:'u',h:t});
 if(!q){m.msgs.push({r:'x',h:'Got it — I added that as an extra instruction.'});renderModal();return}
 if(!q.free){m.msgs.push({r:'x',h:`I added that too: “${esc(t)}”. Now please pick an option above, or type “skip”.`});renderModal();return}
 const L=splitList(t);m.ans[q.k]=['qual','disq','questions','restrict','exclude'].includes(q.k)?L:t;
 m.msgs.push({r:'x',h:`Here’s what I understood:${L.length>1?`<ol>${L.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:`<p>“${esc(t)}”</p>`}<b>Am I correct?</b>`,o:{k:'__verify',items:[['yes','Yes, correct'],['no','Change it']],sel:[]}});renderModal()};
function bApply(){const m=S.modal,A_=m.ans;if(m.ctx==='agent'){const a=curA(),j=a.job;if(A_.purposes)j.purposes=A_.purposes;if(A_.goal)j.goal=A_.goal;if(A_.target)j.target=A_.target;if(A_.exclude)j.exclude={on:true,who:[].concat(A_.exclude).join(', ')};if(A_.products)j.products=A_.products;if(A_.pricing)j.pricing=A_.pricing;if(A_.billing)j.billing=A_.billing;if(A_.qual)j.qual=A_.qual.map(t=>({t,imp:'Required'}));if(A_.disq)j.disq=A_.disq.map(t=>({t,imp:'Required'}));if(A_.questions)j.questions=A_.questions.map(q=>({q:q.endsWith('?')?q:q+'?',req:'Required',att:A_.attempts||'Twice',cond:''}));if(A_.cant)j.cantDecide=A_.cant;if(A_.hand)j.triggers=A_.hand;if(A_.restrict)j.restrict=A_.restrict;if(A_.tone)j.tone=A_.tone;if(A_.posture)j.posture=A_.posture;if(A_.script&&typeof A_.script==='string')j.script=A_.script;a.needsInfo=false;a.score=Math.max(a.score,84);a.ver++;a.versions.push({v:a.ver,label:'Set up with AI',date:'Sep 27'});a.edited=true;closeM();S.ag.sec='job';rr();toast(a.name+' is set up — review score '+a.score+'%',true)}
 else{if(A_.qual)S.wz.qual=A_.qual.map(t=>({t,imp:'Required'}));if(A_.disq)S.wz.disq=A_.disq.map(t=>({t,imp:'Required'}));if(A_.script&&typeof A_.script==='string')S.wz.script=A_.script;if(A_.restrict)S.wz.donts=A_.restrict;closeM();rr();toast('Campaign details filled in by AI',true)}}

