function vLeaderboard(){const f=S.ag.lb;let L=D.agents.filter(a=>(f.type==='all'||a.type===f.type)&&(f.camp==='all'||a.camps.includes(f.camp))&&(f.dir==='all'||a.dir===f.dir||a.dir==='both'));const k=f.sort;L=L.slice().sort((a,b)=>k==='score'?b.score-a.score:(b.ws[k]||0)-(a.ws[k]||0));const mult={'7':.25,'30':1,'90':2.8}[f.period];
 return `<div class="page wide" style="max-width:1400px"><button class="back" data-act="agView" data-v="tiles">${ic('arrowl',14)}AI Agents</button><div class="ph"><div><h1>Agent leaderboard</h1><p class="sub">Compare every agent on every number. Your workspace only — global scores are shown separately.</p></div>${aiBtn('Get a report with AI','toast','data-m="Leaderboard report saved to Reports › AI agents" data-ai="1"','sm')}</div>
 <div class="row" style="margin-bottom:12px">${sel([['all','All types']].concat(Object.entries(AT).map(([k,v])=>[k,v.l])),f.type,'data-chg="lbF" data-k="type"','sm auto')}${sel([['all','All campaigns']].concat(D.campaigns.map(c=>[c.id,c.name])),f.camp,'data-chg="lbF" data-k="camp"','sm auto')}${seg([['all','All'],['out','Outbound','out'],['in','Inbound','in']],f.dir,'lbDir')}${seg([['7','7 days'],['30','30 days'],['90','90 days']],f.period,'lbP')}<span class="grow"></span><span class="small muted">Sort by</span>${sel([['score','Review score'],['conv','Conversion'],['success','Success rate'],['sales','Sales'],['msgs','Messages'],['calls','Calls'],['appts','Appointments'],['resolved','Resolved']],f.sort,'data-chg="lbF" data-k="sort"','sm auto')}</div>
 <div class="card tw"><table class="t"><thead><tr><th>#</th><th>Agent</th><th>Type</th><th class="r">Messages</th><th class="r">Replies</th><th class="r">Calls</th><th class="r">Conversion</th><th class="r">Success</th><th class="r">Sales</th><th class="r">Appointments</th><th class="r">Resolved</th><th class="r">Global</th><th class="r">Review</th></tr></thead><tbody>${L.map((a,i)=>`<tr class="click" data-act="openAgent" data-id="${a.id}"><td class="num">${i+1}</td><td><div class="nm"><span class="av sm bot">${ic(AT[a.type].i,11)}</span><b>${a.name}</b></div></td><td class="small">${AT[a.type].l}</td><td class="r num">${nf(a.ws.msgs*mult)}</td><td class="r num">${nf(a.ws.replies*mult)}</td><td class="r num">${nf(a.ws.calls*mult)}</td><td class="r num">${a.ws.conv}%</td><td class="r num">${a.ws.success}%</td><td class="r num">${a.type==='sales'?nf(a.ws.sales*mult):'—'}</td><td class="r num">${a.type==='reception'?nf(a.ws.appts*mult):'—'}</td><td class="r num">${/support|tech/.test(a.type)?nf(a.ws.resolved*mult):'—'}</td><td class="r num faint">${a.global.success}%</td><td class="r">${bdg(a.score+'%',a.score>84?'good':a.score>70?'warn':'bad')}</td></tr>`).join('')}</tbody></table></div></div>`}
C.lbF=el=>{S.ag.lb[el.dataset.k]=el.value;rr()};A.lbDir=el=>{S.ag.lb.dir=el.dataset.v;rr()};A.lbP=el=>{S.ag.lb.period=el.dataset.v;rr()};
